import{bV as i,aL as s,u as t,G as e}from"./chunks/framework.CzwWnRE6.js";const l="/git/5.jpg",h="/git/6.jpg",u=JSON.parse('{"title":"分支管理","description":"","frontmatter":{"title":"分支管理","date":"2025/06/06 13:50:51","permalink":"/git/3wly7ohh/","sidebarSort":20,"categories":["git"]},"headers":[],"relativePath":"git/分支管理.md","filePath":"git/分支管理.md","lastUpdated":1794464674000}'),p={name:"git/分支管理.md"};function n(d,a,o,r,c,k){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="分支管理" tabindex="-1">分支管理 <a class="header-anchor" href="#分支管理" aria-label="Permalink to &quot;分支管理&quot;">​</a></h1><p>几乎所有的版本控制系统都以某种形式支持分支。 使用分支意味着你可以把你的工作从开发主线上分离 开来进行重大的 Bug 修改、开发新的功能，以免影响开发主线。</p><h2 id="查看本地分支" tabindex="-1">查看本地分支 <a class="header-anchor" href="#查看本地分支" aria-label="Permalink to &quot;查看本地分支&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span></span></code></pre></div><h2 id="创建本地分支" tabindex="-1">创建本地分支 <a class="header-anchor" href="#创建本地分支" aria-label="Permalink to &quot;创建本地分支&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 分支名</span></span></code></pre></div><h2 id="切换分支-checkout" tabindex="-1">切换分支(checkout) <a class="header-anchor" href="#切换分支-checkout" aria-label="Permalink to &quot;切换分支(checkout)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 分支名</span></span></code></pre></div><p>我们还可以直接切换到一个不存在的分支（创建并切换）</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 分支名</span></span></code></pre></div><h2 id="合并分支-merge" tabindex="-1">合并分支(merge) <a class="header-anchor" href="#合并分支-merge" aria-label="Permalink to &quot;合并分支(merge)&quot;">​</a></h2><p>一个分支上的提交可以合并到另一个分支</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 分支名</span></span></code></pre></div><h2 id="删除分支" tabindex="-1">删除分支 <a class="header-anchor" href="#删除分支" aria-label="Permalink to &quot;删除分支&quot;">​</a></h2><p>不能删除当前分支，只能删除其他分支</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 分支名</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> #  删除分支时，需要做各种检查</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 分支名</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 不做任何检查，强制删除</span></span></code></pre></div><h2 id="解决冲突" tabindex="-1">解决冲突 <a class="header-anchor" href="#解决冲突" aria-label="Permalink to &quot;解决冲突&quot;">​</a></h2><p>当两个分支上对文件的修改可能会存在冲突，例如同时修改了同一个文件的同一行，这时就需要手动解决冲突，解决冲突步骤如下：</p><ol><li><p>处理文件中冲突的地方</p></li><li><p>将解决完冲突的文件加入暂存区(add)</p></li><li><p>提交到仓库(commit)</p></li></ol><p>冲突部分的内容处理如下所示：</p><p><img src="`+l+'" alt="冲突"></p><h2 id="开发中分支使用原则与流程" tabindex="-1">开发中分支使用原则与流程 <a class="header-anchor" href="#开发中分支使用原则与流程" aria-label="Permalink to &quot;开发中分支使用原则与流程&quot;">​</a></h2><p>在开发中，一般有如下分支使用原则与流程：</p><ul><li>master（生产）分支</li></ul><blockquote><p>线上分支，主分支，中小规模项目作为线上运行的应用对应的分支；</p></blockquote><ul><li>dev（开发）分支</li></ul><blockquote><p>是从 master 创建的分支，一般作为开发部门的主要开发分支，如果没有其他并行开发不同期上线 要求，都可以在此版本进行开发，阶段开发完成后，需要是合并到 master 分支,准备上线。</p></blockquote><ul><li>feature/xxx（功能）分支</li></ul><blockquote><p>从 develop 创建的分支，一般是同期并行开发，但不同期上线时创建的分支，分支上的研发任务完 成后合并到 develop 分支。</p></blockquote><ul><li>hotfix/xxxx 分支</li></ul><blockquote><p>从 master 派生的分支，一般用于紧急修复线上 bug，修复完成后需要同时合并到 master 分支和 develop 分支。</p></blockquote><p><img src="'+h+'" alt="分支管理"></p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><ol><li><p>创建一个新分支 dev</p><ul><li>git branch dev</li></ul></li><li><p>切换到 dev 分支</p><ul><li>git checkout dev</li></ul></li><li><p>在 dev 分支上添加文件并提交</p><ul><li><p>touch dev.txt</p></li><li><p>git add dev.txt</p></li><li><p>git commit -m &quot;add dev.txt&quot;</p></li></ul></li><li><p>切换回 master 分支</p><ul><li>git checkout master</li></ul></li><li><p>合并 dev 分支到 master 分支</p><ul><li>git merge dev</li></ul></li><li><p>删除 dev 分支</p><ul><li>git branch -d dev</li></ul></li></ol>',34)])])}const b=i(p,[["render",n]]);export{u as __pageData,b as default};
